import csv
import io


def import_text(text, store, dry_run=False):
    # Parse and validate every row before committing any changes.
    planned = []
    for row in csv.DictReader(io.StringIO(text)):
        if any(row.get(key) is None for key in ('sku', 'name', 'qty')):
            raise ValueError('row is missing a field')
        item = {
            'sku': row['sku'].strip(),
            'name': row['name'].strip(),
            'qty': row['qty'].strip(),
        }
        if not item['sku'] or not item['name']:
            raise ValueError('sku and name must be nonempty after trimming')
        if not item['qty'] or not all(c in '0123456789' for c in item['qty']):
            raise ValueError('qty must be a nonnegative decimal integer')
        item['qty'] = int(item['qty'])
        planned.append(item)

    result = {'created': 0, 'updated': 0, 'unchanged': 0, 'changes': []}
    for item in planned:
        before = store.get(item['sku'])
        if before == item:
            result['unchanged'] += 1
            continue
        result['created' if before is None else 'updated'] += 1
        result['changes'].append({'sku': item['sku'], 'before': before, 'after': dict(item)})
        if not dry_run:
            store.put(item)
    return result

